func isValid(_ s: String) -> Bool {
    var stack: [Character] = []
    let map: [Character: Character] = [")": "(", "]": "["]
    for c in s {
        if let match = map[c] {
            if stack.popLast() != match { return false }
        } else {
            stack.append(c)
        }
    }
    return stack.isEmpty
}
print("\(isValid("([])")) \(isValid("([)]"))")

struct SimpleQueue {
    var inStack: [Int] = []
    var outStack: [Int] = []
    mutating func push(_ x: Int) { inStack.append(x) }
    mutating func pop() -> Int {
        if outStack.isEmpty {
            while let item = inStack.popLast() { outStack.append(item) }
        }
        return outStack.popLast() ?? -1
    }
}
var q = SimpleQueue()
q.push(1)
q.push(2)
let a = q.pop()
q.push(3)
let b = q.pop()
print("\(a) \(b)")

func nextGreater(_ nums: [Int]) -> [Int] {
    var result = Array(repeating: -1, count: nums.count)
    var stack: [Int] = []
    for (i, num) in nums.enumerated() {
        while let top = stack.last, nums[top] < num {
            result[top] = num
            stack.removeLast()
        }
        stack.append(i)
    }
    return result
}
print(nextGreater([2, 1, 2, 4, 3]))

func checkUnclosed(_ text: String) -> Bool {
    var stack: [Character] = []
    for c in text {
        if c == "(" { stack.append(c) }
        else if c == ")" {
            if stack.popLast() == nil { return false }
        }
    }
    return stack.isEmpty
}
print(checkUnclosed("((()"))

