func isValidBracketString(_ text: String) -> Bool {
    let matching: [Character: Character] = [")": "(", "]": "[", "}": "{"]
    var stack: [Character] = []
    for char in text {
        if let expectedOpen = matching[char] {
            if stack.popLast() != expectedOpen {
                return false
            }
        } else {
            stack.append(char)
        }
    }
    return stack.isEmpty
}

print(isValidBracketString("({[]})"))
print(isValidBracketString("([)]"))

struct StackQueue<T> {
    private var inbox: [T] = []
    private var outbox: [T] = []
    var isEmpty: Bool { inbox.isEmpty && outbox.isEmpty }
    mutating func enqueue(_ element: T) {
        inbox.append(element)
    }
    mutating func dequeue() -> T? {
        if outbox.isEmpty {
            while let item = inbox.popLast() {
                outbox.append(item)
            }
        }
        return outbox.popLast()
    }
}

var queue = StackQueue<Int>()
queue.enqueue(10)
queue.enqueue(20)
print(queue.dequeue() ?? -1)
print(queue.dequeue() ?? -1)

func dailyTemperatures(_ temps: [Int]) -> [Int] {
    var answer = Array(repeating: 0, count: temps.count)
    var stack: [Int] = []
    for (i, temp) in temps.enumerated() {
        while let top = stack.last, temps[top] < temp {
            answer[top] = i - top
            stack.removeLast()
        }
        stack.append(i)
    }
    return answer
}

print(dailyTemperatures([73, 74, 75, 71, 69, 72, 76, 73]))
